args.code:
#include <iostream>
#include <cstdint>
#include <cstring>
#include <string>

struct Slice {
    const char* data;
    size_t size;
    Slice() : data(nullptr), size(0) {}
    Slice(const char* d, size_t s) : data(d), size(s) {}
    Slice(const std::string& s) : data(s.data()), size(s.size()) {}
};

uint64_t DecodeFixed64(const char* p) {
    uint64_t v;
    std::memcpy(&v, p, 8);
    return v;
}

bool ParseInternalKey(const Slice& internal_key, Slice* user_key, uint64_t* sequence, uint8_t* type) {
    if (internal_key.size() < 8) return false;
    const char* data = internal_key.data;
    size_t size = internal_key.size;

    uint64_t packed = DecodeFixed64(data + size - 8);
    *type = static_cast<uint8_t>(packed & 0xFF);
    *sequence = packed >> 8;
    *user_key = Slice(data, size - 8);
    return true;
}

int main() {
    std::string key_data = "userkey";
    uint64_t seq = 12345;
    uint8_t type = 1;
    uint64_t packed = (seq << 8) | type;

    std::string internal_key_str = key_data;
    internal_key_str.append(reinterpret_cast<const char*>(&packed), 8);

    Slice internal_key(internal_key_str);
    Slice user_key;
    uint64_t res_seq;
    uint8_t res_type;

    if (ParseInternalKey(internal_key, &user_key, &res_seq, &res_type)) {
        std::cout << "UserKey: " << std::string(user_key.data, user_key.size) << std::endl;
        std::cout << "Seq: " << res_seq << std::endl;
        std::cout << "Type: " << (int)res_type << std::endl;
    } else {
        std::cout << "Failed" << std::endl;
    }
    return 0;
}

